-- GENERATED by `wfj generate` from data/gossip/gossip-75.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7503614b360a57b3"] = { "Se è questo che desideri, {class}, devi parlare con Keras Wolfheart sulla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧. È un rappresentante della ⟦The League of Arathor=Lega di Arathor⟧ e può aiutarti a raggiungere il ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["750a39bbf0be7483"] = { "Anche se a Brill non c'è un istruttore di Ingegneria, ce n'è uno giù a ⟦Undercity=Sepulcra⟧. Per arrivarci, va' sul retro delle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧, a sud del paese, e prendi l'ascensore per scendere. Una volta lì, chiedi a una guardia di ⟦Undercity=Sepulcra⟧ indicazioni più precise.", "." },
  ["750cd8cec7a5d195"] = { "Al collo di questa renna c'è una targhetta con il marchio della Masseria Buongusto e un nome: «Metzen».\n\nMetzen ti guarda con occhi tristi e sconsolati. È quasi come se la renna fosse stata immobilizzata da una forza invisibile.", "." },
  ["750e7ffb74705198"] = { "La bandiera dell'⟦Horde=Orda⟧ è tornata alla sua base!", "." },
  ["75198c52189ba9e9"] = { "MORITE, CANI DEMONIACI!", "." },
  ["7519ad2067427415"] = { "Fermati! Le staccherai la testa!", "." },
  ["751a48106ba51c2a"] = { "SQUAWK!! *coff* *coff* Devo smettere di fumare!", "." },
  ["752049c984ee459e"] = { "{name}, hai disturbato il mio riposo!", "." },
  ["75236cb2907c13db"] = { "La statua incombe minacciosa sopra di te.", "." },
  ["7529b8069e71a069"] = { "%s sceglie il bersaglio orco...", "." },
  ["752c477c13bea9b6"] = { "Jack e Jill, ma figurati! L'acqua qui intorno la trasporto tutta io.", "." },
  ["752c5ff7f657861f"] = { "Ecco fatto. Devo tornare al lavoro prima che Rokar mi rifili un altro ceffone perché batto la fiacca.", "." },
  ["752d467d25660008"] = { "Non hai l'aria di <uno/una> <studente/studentessa>...", "." },
  ["752f9ebeed0ecde3"] = { "E ora lo spuntino...", "." },
  ["75334278dd5d00b5"] = { "%s comincia a creparsi e a sgretolarsi.", "." },
  ["7535281c690cdee9"] = { "Ehi, Stone, facciamo un giro del circuito una volta o l'altra? Potremmo fare qualche giro e vedere chi vince.", "." },
  ["75453b80afe7c8f1"] = { "Questo mi sembra familiare. Se continuiamo verso est, penso che potremo... Ahh! Viverna all'attacco!", "." },
  ["754c25b6060b9759"] = { "Forza e resistenza, pazienza e saggezza: ricordale sempre, {name}.", "." },
  ["754c8f95fa8b6e74"] = { "Non dirlo a nessuno, ma nemmeno io so tutto! Se vuoi continuare a imparare, dovresti parlare con il proprietario del negozio, Springspindle Fizzlegear.", "." },
  ["754f03499167e4dc"] = { "Ho appena scoccato una freccia.", "." },
  ["754f2d1bba106f03"] = { "Ti sei <arreso/arresa>. Ho vinto io.", "." },
  ["7553545abe2251a2"] = { "Non posso lasciare il mio posto, {name}, ma c'è un compito da sbrigare. Posso fidarmi di te per portarlo a termine?", "." },
  ["7554b2bae0ae97d9"] = { "Questo raggio di luna ti porterà a ⟦Thunder Bluff=Picco del Tuono⟧. Usalo quando vuoi lasciare la festa.", "." },
  ["756b717639c72a0d"] = { "Mostrami a cosa ho accesso, Lokhtos.", "." },
  ["7577c31e4de605b1"] = { "Ora mettiamo questa terra rara nella mia fioriera...", "." },
  ["7577e9e6d5992cda"] = { "Uff! Che sollievo essere fuori da quella grotta inquietante.", "." },
  ["757ce5b8c4bd3fec"] = { "Vuoi cominciare l'addestramento? Allora cerca di starmi dietro, {name}. Abbiamo molta strada da fare.", "." },
  ["758455eec8d122b1"] = { "Non che io abbia la certezza che tu possa mai, nemmeno in un fantastiliardo di anni, avere abbastanza stranglekelp, con tutto il gelato che serve, ma pare che ne abbiamo abbastanza. O almeno così mi dicono. Sembra che alcuni degli altri qui possano aver bisogno di aiuto con qualunque cosa stiano raccogliendo. Comprensibile, in effetti, se pensi che la loro raccolta non potrebbe mai essere divertente quanto raccogliere stranglekelp.", "." },
  ["7589319e65aae0e2"] = { "INCHINATEVI ALL'ONNIPOTENTE! INCHINATEVI DAVANTI ALLA MIA DISTRU... pollo?", "." },
  ["759125c7612eeff3"] = { "La banca? Oh, intendi The Vault! Non c'è posto più sicuro di The Vault per custodire i tuoi oggetti di valore. Lo trovi appena a nord-est dell'ingresso di ⟦Ironforge=Forgiardente⟧.", "." },
  ["7592db6bdb952cdb"] = { "Assolutamente sì.", "." },
  ["759dc8f693374cb8"] = { "%s rilascia la Sfera di Draenetista Perfetta e la lascia fluttuare davanti a sé.", "." },
  ["75a31397e43b1b3a"] = { "<Bodley ti guarda con aria dubbiosa, ma continua...>\n\nEccoci lì, con il libro degli incantesimi in mano, e Kormok, il nostro negromante ogre a due teste, assume uno strano sguardo in tutti e quattro gli occhi. Era davvero inquietante, perché il secondo paio di occhi sembrava sempre un po' morto, come gli occhi di una mucca, capisci? Così, all'improvviso, allunga la mano e strappa l'amuleto che Valthalak indossava.\n\nIl resto della compagnia diede di matto: alcuni di noi gli dicevano di lasciarlo stare, altri lo volevano per sé.", "." },
  ["75a544b0bc3d4669"] = { "Non ho quasi rifornimenti per i potenziamenti.", "." },
  ["75a63b86b182a6fb"] = { "Maestro, devo fare pipì!", "." },
  ["75aed52f3fe6965c"] = { "Cosa stai cercando?", "." },
  ["75b384bbdd34de9c"] = { "<La misteriosa sfera che tieni ti riempie di un terrore gelido. Ti sembra quasi di sentire una voce echeggiare debolmente nella mente. Bassa e gutturale: capisci bene che la lingua parlata è di natura demoniaca. \r\n\nAnche per <un/una> <paladino/paladina> come te, questa magia è fuori portata. Delgren il Purificatore potrebbe aiutarti a capire la natura di questo oggetto sinistro.>", "." },
  ["75b8df645304e94c"] = { "Prego, seguimi.", "." },
  ["75c44e6a1cfcf4e9"] = { "C'è un modo...", "." },
  ["75c9ebfc41ccaf50"] = { "Sono io che li sfamo, <ragazzo/ragazza>. Già, Daryl Riknussun, al tuo servizio.", "." },
  ["75d0bef9a3cc1dbe"] = { "È un lavoro discreto, lo ammetto. Ma mi faresti più impressione se sbrigassi una faccenda per me.", "." },
  ["75d258b2e74735f2"] = { "Usare i frutti della Madre Terra per creare pozioni che ci aiutino nella nostra eterna lotta è un'impresa onorevole. Per imparare quest'arte devi viaggiare a nord fino alla nostra grande casa, ⟦Thunder Bluff=Picco del Tuono⟧. Quando arrivi in cima, chiedi a uno dei Guardiani del Picco indicazioni più precise.", "." },
  ["75d779b330dab80b"] = { "Se hai altro cuoio spesso, mi dispiace, ma è troppo tardi. Abbiamo tutto quello che ci serve, ma prima di andare, potresti parlare con gli altri qui? È probabile che qualcuno abbia ancora bisogno del tuo aiuto per la sua raccolta.", "." },
  ["75df5f169953e95d"] = { "Non mi aspettavo che foste capaci di tanta organizzazione. L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ hanno entrambe completato i preparativi per la guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Proprio mentre parliamo, il materiale viene spedito a ⟦Silithus=Silitus⟧ e dovrebbe arrivare tutto entro un giorno. Poi spetterà a chi riassemblerà lo Scettro delle Sabbie Mutevoli battere il gong all'Altare dello Scarabeo e aprire le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Allora la guerra comincerà davvero!", "." },
  ["75e117f8de9abd44"] = { "Dai un'occhiata alle mie carni, <amico/amica>. Non vorrai certo addentrarti nelle ⟦Barrens=Savane⟧ senza una buona scorta di provviste.", "." },
  ["75e5c34b1261fdf2"] = { "Sopravvivenza", "." },
  ["75e9fec066d5954b"] = { "Ti prego, teletrasportami a Darnassus.", "." },
  ["75ed5780f471121b"] = { "L'aura di energia arcana che ti circonda è forte, persino per <un/una> <mago/maga> come te. \r\n\nVieni, sediamoci a parlare un po' della natura dell'arcano e della sorte della nostra patria.", "." },
  ["75edbaf9722c2dbd"] = { "Questo raggio di luna conduce a ⟦Stormwind=Roccavento⟧. Usa il tuo invito quando sei <pronto/pronta>.", "." },
  ["75f6784dc660380a"] = { "Ti auguro una splendida Festa del Grande Inverno! Inizia nel modo giusto con le leccornie della Masseria Buongusto!", "." },
  ["75fb73f11b63feca"] = { "<Benvenuto/Benvenuta>! <Benvenuto/Benvenuta> al Darkmoon Zoo Bizarre di Yebb Neblegear: uno scrigno di leggende viventi e stranezze mitiche! Goditi la visita, <amico/amica>!\n\nMa fai attenzione a ciò che tocchi! Queste esposizioni custodiscono manufatti e bestie tanto terribili quanto divine! Potrebbero bruciare la mano maldestra di uno spettatore troppo curioso...", "." },
  ["75ff267834ca94ab"] = { "Ah! Hai paura che faccia male alla tua delicata macchinina da corsa?", "." },
  ["75ffe0f8e1a41b7c"] = { "Ishnu-alah, <fratello/sorella>. Hai notizie da lontano? Il mio cuore anela a notizie di Teldrassil.", "." },
})
